using System.IO;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class EnemySilhouetteCheck{
 public static object Run(){var sheet=new Texture2D(480,96,TextureFormat.RGBA32,false);var rows=new System.Collections.Generic.List<object>();for(int i=0;i<5;i++){var tex=ProceduralInkMotifs.CreateEnemy((EnemyKind)i);var pixels=tex.GetPixels32();int opaque=0,clear=0;for(int j=0;j<pixels.Length;j++){float a=pixels[j].a/255f;if(a>.5f)opaque++;if(a<.01f)clear++;pixels[j]=Color.Lerp(new Color(.94f,.91f,.82f),new Color(.03f,.02f,.02f),a);}sheet.SetPixels32(i*96,0,96,96,pixels);rows.Add(new{kind=((EnemyKind)i).ToString(),opaque,clear,passed=opaque>100&&clear>100});Object.DestroyImmediate(tex);}sheet.Apply();File.WriteAllBytes(Path.GetFullPath("../docs/evidence/enemy-silhouettes-v2.png"),sheet.EncodeToPNG());Object.DestroyImmediate(sheet);File.WriteAllText(Path.GetFullPath("../docs/evidence/enemy-silhouettes-v2.json"),Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
}
